import { useEffect, useRef } from 'react'
import base from '../assets/avatar_base.webp'
import irisL from '../assets/iris_L.png'
import irisR from '../assets/iris_R.png'
import maskL from '../assets/eyemask_L.png'
import maskR from '../assets/eyemask_R.png'

// eye geometry, % of the 848×1200 avatar (generated by eyes3.py)
const EYES = [
  { iris: irisL, mask: maskL, box: [28.42, 34.33, 14.98, 6.5], ir: [25.98, 1.28, 61.42, 100] },
  { iris: irisR, mask: maskR, box: [57.55, 34.17, 14.74, 6.58], ir: [10.4, -2.53, 63.2, 100] },
]
const MAX_X = 13 // % of iris size
const MAX_Y = 6

/** Avatar whose irises follow the cursor; on touch screens they glance around on their own. */
export default function LookingAvatar({ className, alt }: { className: string; alt: string }) {
  const eyes = useRef<(HTMLDivElement | null)[]>([])
  const irises = useRef<(HTMLImageElement | null)[]>([])

  useEffect(() => {
    const cur = [{ x: 0, y: 0 }, { x: 0, y: 0 }]
    const goal = [{ x: 0, y: 0 }, { x: 0, y: 0 }]
    let pointer: { x: number; y: number } | null = null
    let lastMove = 0
    const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches

    const aim = (px: number, py: number) => {
      eyes.current.forEach((el, i) => {
        if (!el) return
        const r = el.getBoundingClientRect()
        const dx = px - (r.left + r.width / 2)
        const dy = py - (r.top + r.height / 2)
        const d = Math.hypot(dx, dy) || 1
        const k = Math.min(1, d / 260) // closer cursor → smaller turn
        goal[i] = { x: (dx / d) * k * MAX_X, y: (dy / d) * k * MAX_Y }
      })
    }
    const onMove = (e: PointerEvent) => {
      if (e.pointerType !== 'mouse') return
      pointer = { x: e.clientX, y: e.clientY }
      lastMove = performance.now()
    }
    const onLeave = () => { pointer = null }
    addEventListener('pointermove', onMove, { passive: true })
    document.documentElement.addEventListener('mouseleave', onLeave)

    // idle glances when there is no mouse (phones) or it has been still for a while
    let nextGlance = 0
    let raf = 0
    const tick = (t: number) => {
      raf = requestAnimationFrame(tick)
      if (pointer && t - lastMove < 4000) aim(pointer.x, pointer.y)
      else if (!reduce && t > nextGlance) {
        const gx = (Math.random() * 2 - 1) * MAX_X * 0.8
        const gy = (Math.random() * 2 - 1) * MAX_Y * 0.7
        const center = Math.random() < 0.35
        goal[0] = goal[1] = center ? { x: 0, y: 0 } : { x: gx, y: gy }
        nextGlance = t + 1200 + Math.random() * 2200
      }
      irises.current.forEach((el, i) => {
        if (!el) return
        cur[i].x += (goal[i].x - cur[i].x) * 0.18
        cur[i].y += (goal[i].y - cur[i].y) * 0.18
        el.style.transform = `translate(${cur[i].x.toFixed(2)}%, ${cur[i].y.toFixed(2)}%)`
      })
    }
    raf = requestAnimationFrame(tick)
    return () => {
      cancelAnimationFrame(raf)
      removeEventListener('pointermove', onMove)
      document.documentElement.removeEventListener('mouseleave', onLeave)
    }
  }, [])

  return (
    <div className="relative mx-auto w-fit">
      <img src={base} alt={alt} width={848} height={1200} draggable={false} className={className} />
      {EYES.map((e, i) => (
        <div
          key={i}
          ref={(el) => { eyes.current[i] = el }}
          aria-hidden="true"
          className="pointer-events-none absolute overflow-hidden"
          style={{
            left: `${e.box[0]}%`, top: `${e.box[1]}%`, width: `${e.box[2]}%`, height: `${e.box[3]}%`,
            WebkitMaskImage: `url(${e.mask})`, maskImage: `url(${e.mask})`,
            WebkitMaskSize: '100% 100%', maskSize: '100% 100%',
          }}
        >
          <img
            ref={(el) => { irises.current[i] = el }}
            src={e.iris}
            alt=""
            draggable={false}
            className="absolute max-w-none select-none will-change-transform"
            style={{ left: `${e.ir[0]}%`, top: `${e.ir[1]}%`, width: `${e.ir[2]}%`, height: `${e.ir[3]}%` }}
          />
        </div>
      ))}
    </div>
  )
}
